// GET /  The packages by category and how it works.
function handle(req) {
  const lang = langOf(req), groups = [], byName = {};
  for (const p of db.query('SELECT * FROM packages WHERE active = 1 ORDER BY id')) {
    const v = packageView(p, lang);
    if (!byName[p.category]) groups.push(byName[p.category] = {name: v.category, packages: []});
    byName[p.category].packages.push(v);
  }
  return {template: 'home', data: page(req, {groups: groups})};
}

