// GET /packages/:id  One package with the enquiry form (for signed-in visitors).
function handle(req) {
  const p = db.query('SELECT * FROM packages WHERE id = ? AND active = 1', Number(req.params.id))[0];
  if (!p) return notFound(req);
  const u = req.user;
  return {template: 'package', data: page(req, {pkg: packageView(p, langOf(req)),
    form: formOf({package_id: p.id, name: u && u.name, email: u && u.email, phone: u && u.phone})})};
}

